1	"use client";
2	
3	import { useMemo, useState, useTransition } from "react";
4	import { orderGameServer } from "@/lib/actions-gameplans";
5	import { ANNUAL_TERM_MONTHS, termPriceCents, DEFAULT_ANNUAL_DISCOUNT_PCT } from "@/lib/billing-terms";
6	import { TermLadder } from "@/components/customer/TermLadder";
7	import { GameLogo } from "@/components/marketing/GameLogo";
8	
9	export type Tier = {
10	  id: string;
11	  gameFamily: string;
12	  name: string;
13	  ramMB: number;
14	  cpuCores: number;
15	  diskGB: number;
16	  slots: number | null;
17	  priceCents: number;
18	  termMonths: number;
19	  featured: boolean;
20	};
21	export type GameMeta = { family: string; name: string; glyph: string };
22	
23	const money = (c: number) => `$${(c / 100).toFixed(2)}`;
24	const gb = (mb: number) => `${(mb / 1024).toFixed(mb % 1024 ? 1 : 0)} GB`;
25	
26	/**
27	 * Customer game-server deploy: pick a game, pick a tier, deploy. Charges the
28	 * tier's price from the wallet via orderGameServer (which redirects to the new
29	 * server on success).
30	 */
31	export function GameDeploy({
32	  games,
33	  tiers,
34	  balanceCents,
35	  annualDiscountPct = DEFAULT_ANNUAL_DISCOUNT_PCT,
36	}: {
37	  games: GameMeta[];
38	  tiers: Tier[];
39	  balanceCents: number;
40	  /** Live admin annual discount (%), so the Annual card shows the REAL price/savings. */
41	  annualDiscountPct?: number;
42	}) {
43	  const firstGame = games[0]?.family ?? "";
44	  const [game, setGame] = useState(firstGame);
45	  const [selected, setSelected] = useState<string | null>(null);
46	  // Annual is the recommended, better-value default; monthly stays one click away.
47	  const [termMonths, setTermMonths] = useState(ANNUAL_TERM_MONTHS);
48	  const [error, setError] = useState<string | null>(null);
49	  const [pending, start] = useTransition();
50	
51	  const gameTiers = useMemo(
52	    () => tiers.filter((t) => t.gameFamily === game).sort((a, b) => a.priceCents - b.priceCents),
53	    [tiers, game],
54	  );
55	
56	  const chosen = gameTiers.find((t) => t.id === selected) ?? null;
57	  // What this order costs at the chosen term — the SAME formula the server charges
58	  // (termPriceCents), so what's shown here is what's charged and renewed.
59	  const chargeCents = chosen ? termPriceCents(chosen.priceCents, termMonths, annualDiscountPct) : 0;
60	  const insufficient = chosen ? balanceCents < chargeCents : false;
61	
62	  function deploy() {
63	    if (!chosen) return;
64	    setError(null);
65	    start(async () => {
66	      const res = await orderGameServer(chosen.id, termMonths);
67	      // On success orderGameServer redirects; only errors return here.
68	      if (res?.error) setError(res.error);
69	    });
70	  }
71	
72	  return (
73	    <div className="space-y-6">
74	      {/* Step 1 — game */}
75	      <div>
76	        <p className="label mb-2">1 · Choose a game</p>
77	        <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-6">
78	          {games.map((g) => {
79	            const active = g.family === game;
80	            const count = tiers.filter((t) => t.gameFamily === g.family).length;
81	            return (
82	              <button
83	                key={g.family}
84	                onClick={() => {
85	                  setGame(g.family);
86	                  setSelected(null);
87	                  setError(null);
88	                }}
89	                className={`card card-hover flex flex-col items-center gap-1.5 py-4 text-center transition ${
90	                  active ? "border-brand-400 ring-1 ring-brand-400/40" : ""
91	                }`}
92	              >
93	                <GameLogo family={g.family} size={40} />
94	                <span className="text-sm font-medium text-white">{g.name}</span>
95	                <span className="text-[11px] text-slate-500">
96	                  {count} tier{count === 1 ? "" : "s"}
97	                </span>
98	              </button>
99	            );
100	          })}
101	        </div>
102	      </div>
103	
104	      {/* Step 2 — tier */}
105	      <div>
106	        <p className="label mb-2">2 · Choose a plan</p>
107	        {gameTiers.length === 0 ? (
108	          <p className="text-sm text-slate-500">No plans are available for this game yet. Check back soon.</p>
109	        ) : (
110	          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
111	            {gameTiers.map((t) => {
112	              const active = t.id === selected;
113	              return (
114	                <button
115	                  key={t.id}
116	                  onClick={() => {
117	                    setSelected(t.id);
118	                    setError(null);
119	                  }}
120	                  className={`card card-hover text-left transition ${
121	                    active ? "border-brand-400 ring-1 ring-brand-400/40" : ""
122	                  }`}
123	                >
124	                  <div className="flex items-center justify-between gap-2">
125	                    <span className="font-semibold text-white">{t.name}</span>
126	                    {t.featured && (
127	                      <span className="rounded-full border border-brand-500/40 bg-brand-500/10 px-2 py-0.5 text-[11px] text-brand-300">
128	                        Popular
129	                      </span>
130	                    )}
131	                  </div>
132	                  <p className="mt-2 text-2xl font-bold tracking-tight text-white">
133	                    {money(t.priceCents)}
134	                    <span className="text-sm font-normal text-slate-400">
135	                      {t.termMonths > 1 ? ` / ${t.termMonths} mo` : " / mo"}
136	                    </span>
137	                  </p>
138	                  <ul className="mt-3 space-y-1 text-sm text-slate-400">
139	                    <li>{gb(t.ramMB)} RAM · {t.cpuCores} vCPU</li>
140	                    <li>{t.diskGB} GB NVMe disk</li>
141	                    {t.slots != null && <li>Up to {t.slots} player slots</li>}
142	                  </ul>
143	                </button>
144	              );
145	            })}
146	          </div>
147	        )}
148	      </div>
149	
150	      {/* Step 3 — billing term */}
151	      {chosen && (
152	        <div>
153	          <p className="label mb-2">3 · Billing term</p>
154	          <TermLadder
155	            monthlyCents={chosen.priceCents}
156	            annualDiscountPct={annualDiscountPct}
157	            value={termMonths}
158	            onChange={setTermMonths}
159	          />
160	        </div>
161	      )}
162	
163	      {/* Step 4 — deploy */}
164	      {chosen && (
165	        <div className="card flex flex-wrap items-center justify-between gap-4">
166	          <div>
167	            <p className="text-sm text-slate-400">
168	              Deploying <span className="font-medium text-white">{chosen.name}</span>. You&apos;ll be charged{" "}
169	              <span className="font-medium text-white">{money(chargeCents)}</span> from your wallet
170	              (balance {money(balanceCents)}).
171	            </p>
172	            {error && <p className="mt-1 text-sm text-red-400">{error}</p>}
173	            {insufficient && !error && (
174	              <p className="mt-1 text-sm text-amber-400">Insufficient balance — top up your wallet first.</p>
175	            )}
176	          </div>
177	          <button className="btn-primary" disabled={pending || insufficient} onClick={deploy}>
178	            {pending ? "Deploying…" : "Deploy server"}
179	          </button>
180	        </div>
181	      )}
182	    </div>
183	  );
184	}
