230	/**
231	 * Pick the least-committed enabled node (RAM headroom), while steering AWAY from
232	 * a node this order would push to/past the CRITICAL capacity threshold when
233	 * another node has room. Falls back to primary (any node) when every candidate is
234	 * already critical — the scheduler never REFUSES an order for a capacity warning
235	 * (that's the node-capacity alert's job, lib/node-capacity.ts); it only prefers a
236	 * roomier node when one exists. DB-only so order placement never blocks on a
237	 * Proxmox round trip.
238	 */
239	async function scheduleNode(planRamMB: number) {
240	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
241	  if (nodes.length === 0) return null;
242	  const loads = await Promise.all(
243	    nodes.map(async (n) => {
244	      const agg = await db.server.findMany({
245	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
246	        select: { plan: { select: { ramMB: true } } },
247	      });
248	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
249	      // Commitment AFTER this VM lands — that's what decides whether placing here
250	      // tips the node critical.
251	      const projectedPct = n.capacityRamMB > 0 ? ((used + planRamMB) / n.capacityRamMB) * 100 : 100;
252	      return { node: n, free: n.capacityRamMB - used, projectedPct };
253	    }),
254	  );
255	  const { critPct } = await nodeThresholds();
256	  const roomy = loads.filter((l) => l.projectedPct < critPct);
257	  const pool = roomy.length > 0 ? roomy : loads;
258	  pool.sort((a, b) => b.free - a.free);
259	  return pool[0].node;
260	}
