484	/**
485	 * Read-only mirror of `claimOrderCoupon`'s per-person guards, for the CARD path.
486	 *
487	 * The card leg discounts `cardCents` up front and only settles the redemption
488	 * AFTER the card is charged — where a failed claim is deliberately swallowed so a
489	 * paid provision is never stranded. Without this pre-check, a customer who has
490	 * already used a one-per-person code (or isn't first-time) still gets the
491	 * discounted card charge and the swallow hides it. So before we send them to
492	 * checkout we re-run first-time-only, one-per-account, one-per-IP and the cap as
493	 * plain reads; if any fails the caller re-quotes at full price. This is advisory
494	 * (a race could still lose the atomic claim at settle time — that path stays
495	 * swallowed by design), but it closes the everyday bypass.
496	 */
497	export async function orderCouponClaimable(opts: {
498	  couponId: string;
499	  firstTimeOnly: boolean;
500	  maxRedemptions: number | null;
501	  userId: string;
502	  ipHash: string | null;
503	}): Promise<{ ok: true } | { ok: false; error: string }> {
504	  if (opts.firstTimeOnly) {
505	    const prior = await db.server.count({ where: { userId: opts.userId, isFree: false } });
506	    if (prior > 0) return { ok: false, error: "This code is for first-time customers only." };
507	  }
508	  const byUser = await db.couponRedemption.findUnique({
509	    where: { couponId_userId: { couponId: opts.couponId, userId: opts.userId } },
510	  });
511	  if (byUser) return { ok: false, error: "You’ve already used this code." };
512	  if (opts.ipHash) {
513	    const byIp = await db.couponRedemption.findFirst({ where: { couponId: opts.couponId, ipHash: opts.ipHash } });
514	    if (byIp) return { ok: false, error: "This code has already been claimed from your connection." };
515	  }
516	  if (opts.maxRedemptions !== null) {
517	    const c = await db.coupon.findUnique({ where: { id: opts.couponId }, select: { timesRedeemed: true, active: true } });
518	    if (!c || !c.active || c.timesRedeemed >= opts.maxRedemptions) return { ok: false, error: "This code has reached its redemption limit." };
519	  }
520	  return { ok: true };
521	}
