523	export async function placeOrder(
524	  user: User,
525	  intent: OrderIntent,
526	  sold?: OrderPrice | null,
527	  opts?: {
528	    ipHash?: string | null;
529	    campaign?: string;
530	    promoReservationToken?: string | null;
531	    couponReservationToken?: string | null;
532	  },
533	): Promise<string> {
534	  const quote = await orderQuote(intent);
535	  const { plan, os, term, promo, promoCreditCents, extraDiskGB, extraDiskMonthlyCents, extraDiskCents, backupTier, backupMonthlyCents, backupCents } = quote;
536	  // Everything below bills off THESE three, never off `quote.chargeCents` /
537	  // `promo` directly: when a sold price is present it is the whole truth about
538	  // what this order costs and what rate it was sold at.
539	  const chargeCents = sold?.chargeCents ?? quote.chargeCents;
540	  const promoPercent = sold?.promoPercent ?? promo.discountPercent;
541	  const promoName = sold?.promoName || promo.name;
542	  // Note the intro discount on the billing document (first term only; renews full).
543	  const promoNote = promoPercent > 0 ? ` · ${promoName} ${promoPercent}% off first term` : "";
544	
545	  // Managed first-month-free — how this order settles the credit depends on the path:
546	  //   WALLET path (no `sold`): the credit rides on the fresh quote (promoCreditCents
547	  //     > 0), and we contend for it with an atomic INSERT inside the charge tx below.
548	  //   CARD/Stripe path (`sold` present): the credit was already RESERVED before the
549	  //     card was charged, and its hold token travels in `opts.promoReservationToken`.
550	  //     We CONFIRM that hold (never a fresh contended INSERT) — that is what closes
551	  //     the double-claim race. No token => this order was sold at FULL price, so there
552	  //     is nothing to grant. We deliberately do NOT infer the credit from
553	  //     `sold.promoPercent` (currentPromo always stamps 100, even on a full-price VPS
554	  //     order), which would record a redemption for a purchase that never got one.
555	  const walletPromoApplied = !sold && promoCreditCents > 0;
556	  const cardPromoToken = sold ? opts?.promoReservationToken ?? null : null;
557	  // The checkout coupon settles the same two ways:
558	  //   WALLET path (no `sold`): atomic claim in its OWN tx below (claimOrderCoupon), which
559	  //     throws and surfaces before any money moves if the last slot just went.
560	  //   CARD/Stripe path (`sold`): the coupon was RESERVED before the card was charged and
561	  //     its hold token travels in `opts.couponReservationToken`. We CONFIRM that hold
562	  //     inside the charge tx (never a fresh contended claim — that would double-count the
563	  //     global cap and collide on the per-person unique). No token => full-price order.
564	  const cardCouponToken = sold ? opts?.couponReservationToken ?? null : null;
565	
566	  const cap = await capacityCheck(plan.id);
567	  if (!cap.ok) throw new OrderError(cap.reason);
568	
569	  let nodeId: string | null = null;
570	  if (intent.nodeId) {
571	    const n = await db.node.findFirst({ where: { id: intent.nodeId, enabled: true } });
572	    if (!n) throw new OrderError("Selected location is not available.");
573	    nodeId = n.id;
574	  } else {
575	    const n = await scheduleNode(plan.ramMB);
576	    nodeId = n?.id ?? null;
577	  }
578	
579	  // Reserve the EFFECTIVE size (plan + upsold extra) — the VM really is that big.
580	  const diskCap = await diskCapacityCheck(nodeId, effectiveDiskGB(plan.diskGB, extraDiskGB));
581	  if (!diskCap.ok) throw new OrderError(diskCap.reason);
582	
583	  const addons = {
584	    malwareScanner: !!intent.addonMalware,
585	    dailyBackup: !!intent.addonBackup,
586	    docker: !!intent.addonDocker,
587	  };
588	  const isAdmin = user.role === "ADMIN";
589	  const freeRequested = !!intent.free && isAdmin;
590	
591	  // VAT/GST to add to this order (Finding 1). CARD path: settle exactly the tax the
592	  // card leg was split from, carried on `sold` (never re-quoted after the card
593	  // cleared). WALLET path: resolve from the owner's billing country now. The RATE is
594	  // resolved here; the tax cents are recomputed from it inside the charge tx against
595	  // the amount actually debited, so a promo-lost full-price recompute is taxed on the
596	  // real net rather than the discounted one. A free admin grant is never taxed.
597	  let taxRatePercent = 0;
598	  let taxCountry = "";
599	  if (!freeRequested) {
600	    if (sold) {
601	      taxRatePercent = sold.taxRatePercent ?? 0;
602	      taxCountry = sold.taxCountry ?? "";
603	    } else {
604	      const ctx = await taxContextForUser(user);
605	      taxRatePercent = ctx.ratePercent;
606	      taxCountry = ctx.country;
607	    }
608	  }
609	  const orderTaxCents = Math.round((chargeCents * taxRatePercent) / 100);
610	
611	  if (!freeRequested && user.balanceCents < chargeCents + orderTaxCents) throw new OrderError("Insufficient balance.");
612	
613	  // Hard monthly spend cap (Finding 3): refuse a new paid order that would push this
614	  // account past its own cap. No-op unless the customer enabled one. Surfaced as an
615	  // OrderError so the deploy action shows the message verbatim.
616	  if (!freeRequested) {
617	    try {
618	      await assertSpendCap(user, chargeCents + orderTaxCents);
619	    } catch (e) {
620	      if (e instanceof SpendCapError) throw new OrderError(e.message);
621	      throw e;
622	    }
623	  }
624	
625	  // WALLET path ONLY: claim the coupon atomically BEFORE the order tx, so a wallet order
626	  // fails cleanly (no money moved) if the last slot just went. A free admin grant never
627	  // consumes a customer coupon. The CARD path does NOT claim here — it reserved the coupon
628	  // before checkout and CONFIRMS that hold inside the charge tx below (`cardCouponToken`),
629	  // which is what closes the concurrent-checkout bypass the read-then-swallow left open.
630	  if (!freeRequested && !sold && quote.couponId && quote.couponDiscountCents > 0) {
631	    await claimOrderCoupon({
632	      couponId: quote.couponId,
633	      maxRedemptions: quote.couponMaxRedemptions,
634	      firstTimeOnly: quote.couponFirstTimeOnly,
635	      userId: user.id,
636	      ipHash: opts?.ipHash ?? null,
637	      amountCents: quote.couponDiscountCents,
638	    });
639	  }
640	
641	  const newKey = (intent.sshPublicKey ?? "").trim();
642	  const keyName = (intent.sshKeyName ?? "deploy-key").slice(0, 60);
643	
644	  let server;
645	  try {
646	    server = await db.$transaction(async (tx) => {
647	      // ATOMIC first-month-free claim, INSIDE the charge tx (mirrors claimOrderCoupon).
648	      // Contend for the redemption BEFORE debiting so the debit amount matches the
649	      // outcome. A lost claim never throws — on the wallet path we add the credit
650	      // back and charge FULL; on the card path the money already settled at the sold
651	      // price (screened by the pre-checkout guard in actions.ts), so we keep it and
652	      // record nothing — the same swallow discipline the coupon path uses.
653	      let debitCents = chargeCents;
654	      let promoNoteFinal = promoNote;
655	      let promoClaimId: string | null = null;
656	      let soldFull = false; // wallet order that lost the claim and paid full price
657	      if (!freeRequested && cardPromoToken) {
658	        // CARD/Stripe path: confirm the hold reserved before the card was charged.
659	        // The card already settled at the sold (discounted) price; confirming just
660	        // flips the hold to CONSUMED and anchors it. NEVER a second debit here.
661	        const confirmed = await confirmReservation(tx, cardPromoToken);
662	        if (confirmed) {
663	          promoClaimId = confirmed.id;
664	        } else {
665	          // The hold is gone (released/swept) but the card already paid the discounted
666	          // leg. This is unreachable while the hold outlives the payable session, but
667	          // if it ever happens we must NOT charge more than the customer was shown.
668	          // Try to record the grant so a later renewal can convert it; if even that
669	          // loses (the slot is now another order's), keep the discounted charge and
670	          // log — the same swallow discipline the paid-coupon path uses.
671	          const fallback = await claimFirstMonthFree(tx, {
672	            userId: user.id,
673	            ipHash: opts?.ipHash ?? null,
674	            serviceType: "VPS",
675	            campaign: opts?.campaign ?? "",
676	            chargedCents: chargeCents,
677	          });
678	          if (fallback.claimed) promoClaimId = fallback.id;
679	          else console.error(`[order] first-month-free hold ${cardPromoToken} vanished before confirm for ${user.id}; kept sold price`);
680	        }
681	      } else if (!freeRequested && walletPromoApplied) {
682	        // WALLET path: atomic INSERT inside the charge tx. A lost claim means this
683	        // account/IP already redeemed — add the credit back and charge FULL price.
684	        const claim = await claimFirstMonthFree(tx, {
685	          userId: user.id,
686	          ipHash: opts?.ipHash ?? null,
687	          serviceType: "VPS",
688	          campaign: opts?.campaign ?? "",
689	          chargedCents: chargeCents,
690	        });
691	        if (claim.claimed) {
692	          promoClaimId = claim.id;
693	        } else {
694	          debitCents = chargeCents + promoCreditCents; // full price
695	          promoNoteFinal = "";
696	          soldFull = true;
697	        }
698	      }
699	      // CARD/Stripe path: confirm the coupon hold reserved before the card was charged
700	      // (RESERVED→CONSUMED), inside this tx so the discount's slot commits with the
701	      // provision. NEVER a fresh claim — that would re-increment the cap and collide on
702	      // the per-person unique. `sold` already carries the discounted total the customer
703	      // paid, so no debit changes here.
704	      if (!freeRequested && cardCouponToken) {
705	        const confirmed = await confirmOrderCouponReservation(tx, cardCouponToken);
706	        if (!confirmed) {
707	          // The hold is gone (released/swept) but the card already settled the discounted
708	          // leg. Unreachable while the hold outlives the payable session (its reservedUntil
709	          // is pinned past the Checkout expiry); if it ever happens we keep the discounted
710	          // charge (never overcharge past what was shown) and log — the same swallow
711	          // discipline the paid path uses. We do NOT mint a replacement claim (its cap
712	          // increment could over-redeem).
713	          console.error(`[order] coupon hold ${cardCouponToken} vanished before confirm for paid order ${user.id}; kept sold price`);
714	        }
715	      }
716	      // The rate this term was actually sold at: 0% off when a wallet order lost the
717	      // claim and paid full, otherwise the promo/sold percent (100 admin grant).
718	      const effectivePromoPercent = freeRequested ? 100 : soldFull ? 0 : promoPercent;
719	      if (!freeRequested) {
720	        // For a multi-month term (Annual etc.), spell out the effective monthly-
721	        // equivalent of the PLAN portion on the billing document, derived from the
722	        // very `regularPlanCents` that was charged (its term discount already baked
723	        // in) — never a second computation. So an annual line reads "Annual
724	        // ($8.09/mo)" and the customer can see the yearly commitment AND its real
725	        // per-month rate. Omitted for the 1-month term, where it would just repeat
726	        // the monthly price.
727	        const effMonthlyCents = term.months > 1 ? Math.round(quote.regularPlanCents / term.months) : 0;
728	        const termLabel =
729	          term.months > 1 ? `${term.label} ($${(effMonthlyCents / 100).toFixed(2)}/mo)` : term.label;
730	        // VAT/GST on the NET actually being debited (recomputed from the rate so the
731	        // promo-lost full-price recompute above is taxed correctly). The wallet debit
732	        // and the invoice total are both net + tax; the line items sum to the net.
733	        const orderTaxFinal = Math.round((debitCents * taxRatePercent) / 100);
734	        const grossDebit = debitCents + orderTaxFinal;
735	        await debitWallet(tx, user.id, grossDebit);
736	        await tx.walletTransaction.create({
737	          data: {
738	            userId: user.id,
739	            amountCents: -grossDebit,
740	            description: `Order: ${plan.name} VPS (${intent.hostname}) — ${termLabel}${promoNoteFinal}`,
741	          },
742	        });
743	        // Billing document for the charge — created inside the same debit tx so it
744	        // shares the transaction's atomicity (a rolled-back charge leaves no invoice).
745	        // Extra disk gets its OWN line so the customer can see exactly what the
746	        // permanent storage costs; the lines always sum back to debitCents.
747	        const lineDesc = `${plan.name} VPS (${intent.hostname}) — ${termLabel}${promoNoteFinal}`;
748	        // Both add-ons get their OWN line; the base plan line is the remainder, so
749	        // the lines always sum back to debitCents.
750	        const planLineCents = debitCents - extraDiskCents - backupCents;
751	        await tx.invoice.create({
752	          data: invoiceCreateData({
753	            userId: user.id,
754	            description: lineDesc,
755	            status: "PAID",
756	            taxCents: orderTaxFinal,
757	            taxRatePercent,
758	            taxCountry,
759	            period: { start: new Date(), end: addMonths(new Date(), term.months) },
760	            lineItems: [
761	              { description: lineDesc, qty: 1, unitCents: planLineCents, amountCents: planLineCents },
762	              ...(extraDiskCents > 0
763	                ? [
764	                    {
765	                      description:
766	                        `${extraDiskLabel(extraDiskGB)} — ${term.label} ` +
767	                        `($${(extraDiskMonthlyCents / 100).toFixed(2)}/mo, permanent: storage can be added but never removed)`,
768	                      qty: 1,
769	                      unitCents: extraDiskCents,
770	                      amountCents: extraDiskCents,
771	                    },
772	                  ]
773	                : []),
774	              ...(backupCents > 0
775	                ? [
776	                    {
777	                      description:
778	                        `${backupTierSpec(backupTier).label} backups (keep ${backupTierSpec(backupTier).keep}) — ${term.label} ` +
779	                        `($${(backupMonthlyCents / 100).toFixed(2)}/mo)`,
780	                      qty: 1,
781	                      unitCents: backupCents,
782	                      amountCents: backupCents,
783	                    },
784	                  ]
785	                : []),
786	            ],
787	          }),
788	        });
789	      }
790	      if (newKey && /^(ssh-(rsa|ed25519)|ecdsa-sha2-\S+)\s+\S+/.test(newKey)) {
791	        const exists = await tx.sshKey.findFirst({ where: { userId: user.id, publicKey: newKey } });
