793	      }
794	      const s = await tx.server.create({
795	        // Cast: the symlinked prod Prisma client's types predate `annualDiscountPct`
796	        // (regenerated at deploy — identical at runtime then; see lib/promo-redemption.ts).
797	        data: {
798	          name: intent.hostname,
799	          hostname: intent.hostname,
800	          userId: user.id,
801	          planId: plan.id,
802	          osTemplateId: os.id,
803	          nodeId,
804	          addons,
805	          // The wizard sells "Daily auto-backups" ("Nightly snapshots to separate
806	          // storage for easy restore") and re-confirms it on the Review step, but
807	          // `addons.dailyBackup` was write-only: the worker declares the key and
808	          // never reads it, and the REAL scheduler (worker/backup-schedule.ts)
809	          // keys off `autoBackup` + `backupIntervalHours`, whose only writer was
810	          // the Backups tab. Nothing bridged the two, so EVERY server in the live
811	          // DB carried `addons.dailyBackup` with `autoBackup: false` and no backup
812	          // job was ever enqueued. A customer would discover the safety net they
813	          // were promised did not exist at the moment they needed it. Bridge it
814	          // here, at the point of sale. A PAID backup tier (PLUS) implies backups
815	          // are on regardless of the free "Daily auto-backups" toggle — you cannot
816	          // sell retention on a schedule that never runs. `backupTier`/`backupKeep`
817	          // are the columns the retention lever (worker/index.ts backupCreate)
818	          // reads; keep null on FREE so it falls back to the tier default.
819	          autoBackup: !!intent.addonBackup || backupTier !== "FREE",
820	          backupIntervalHours:
821	            !!intent.addonBackup || backupTier !== "FREE" ? backupTierSpec(backupTier).intervalHours : null,
822	          backupTier,
823	          backupKeep: backupTier === "FREE" ? null : backupTierSpec(backupTier).keep,
824	          termMonths: term.months,
825	          // THE RATE THIS TERM WAS SOLD AT, recorded at the moment of sale. Every
826	          // later proration prices the plan delta against this number instead of
827	          // whatever promo happens to be running when the customer clicks resize
828	          // (lib/proration.ts) — otherwise the customer chooses the rate for each
829	          // half of a round trip by choosing the date, and pockets the spread.
830	          // `chargeCents` above is literally promoPriceCents(regular, promo), so
831	          // this scalar and the cash collected describe the same transaction.
832	          // A free admin grant recorded as 100: nothing was paid for these months,
833	          // so nothing may ever prorate out of them.
834	          //
835	          // `effectivePromoPercent` — not `promo.discountPercent` — because a
836	          // card-paid order settles the rate it was SOLD at (see OrderPrice), which
837	          // may no longer be the promo running now, AND because a wallet order that
838	          // lost the first-month-free claim paid FULL price (0% off): recording 100
839	          // there would let a later downgrade prorate out a discount nobody was
840	          // charged. Recording today's rate against a price collected under a
841	          // different one is exactly the drift this column exists to prevent.
842	          termPromoPercent: effectivePromoPercent,
843	          // The ANNUAL discount rate in force when this term was sold, frozen here so
844	          // every later proration prices against it and an up-then-down round trip nets
845	          // to zero even if the admin retunes `annual_discount_percent` in between
846	          // (Finding 2). Ignored for non-annual terms by `termDiscountPct`; a free admin
847	          // grant never prorates, so its value is inert. `quote.annualPct` is the very
848	          // rate `regularPlanCents`/`chargeCents` above were priced at.
849	          annualDiscountPct: quote.annualPct,
850	          // The plan-portion cash actually collected for this term, net of promo AND
851	          // coupon, EXCLUDING recurring add-ons — the authoritative refund basis (see
852	          // Server.refundableTermCents). `regularPlanCents` is the full term list;
853	          // subtract the promo credit ONLY if the claim held (a lost wallet claim paid
854	          // full, `soldFull`), and always subtract the coupon (it reduced cash but never
855	          // `termPromoPercent`). Clamped ≥ 0. A free admin grant collected nothing, so 0.
856	          refundableTermCents: freeRequested
857	            ? 0
858	            : Math.max(
859	                0,
860	                quote.regularPlanCents - (soldFull ? 0 : promoCreditCents) - quote.couponDiscountCents,
861	              ),
862	          // Persisted BEFORE the PROVISION job runs, so the worker clones the VM
863	          // and resizes scsi0 straight to plan.diskGB + extraDiskGB — the server is
864	          // born at its full size, with no separate expansion job.
865	          extraDiskGB,
866	          wantsDedicatedIp: !!intent.dedicatedIp,
867	          isFree: freeRequested,
868	          expiresAt: freeRequested ? null : addMonths(new Date(), term.months),
869	        } as Prisma.ServerUncheckedCreateInput,
870	      });
871	      await tx.job.create({ data: { type: "PROVISION", serverId: s.id } });
872	      // Anchor the redemption to the created server so the renewal worker can flip
873	      // `renewed` when this customer bills their second term, and stamp the true
874	      // first-term charge. Same tx, so it commits (or rolls back) with the order.
875	      if (promoClaimId) await setPromoOrderRef(tx, promoClaimId, s.id, debitCents);
876	      return s;
877	    });
878	  } catch (e) {
879	    if (e instanceof InsufficientBalanceError) throw new OrderError("Insufficient balance.");
880	    throw e;
881	  }
882	
883	  await db.auditLog.create({
884	    data: {
885	      userId: user.id,
886	      action: "server.order",
887	      detail: `${server.id} image=${os.slug} plan=${plan.slug} term=${term.months}mo extraDisk=${extraDiskGB}GB free=${freeRequested}`,
888	    },
889	  });
890	  if (!freeRequested) {
891	    try {
892	      await maybeRewardReferral(user.id);
893	    } catch {
894	      /* non-fatal */
895	    }
896	    // Soft monthly-budget alert (Finding 3): fire once when this charge tips spend
897	    // over the customer's budget. Best-effort — never fails an order.
898	    await maybeAlertBudget(user.id);
899	  }
900	  return server.id;
901	}
