35	/**
36	 * Claim exclusive responsibility for fulfilling `sessionId`.
37	 * Returns false when another caller already holds the claim — the UNIQUE index,
38	 * not a read-then-write check, is what makes this safe under concurrency.
39	 */
40	async function claim(sessionId: string, kind: string): Promise<boolean> {
41	  try {
42	    await db.fulfilledSession.create({ data: { stripeSessionId: sessionId, kind } });
43	    return true;
44	  } catch (e) {
45	    if ((e as { code?: string })?.code === "P2002") return false; // someone else has it
46	    throw e;
47	  }
48	}
