204	/**
205	 * Create a Checkout session that pays for a prorated per-server DISK EXPANSION
206	 * directly (no wallet pre-fund), applying the customer's wallet balance to the
207	 * split. Structurally identical to createResizeCheckout: the CARD is charged only
208	 * `cardCents` (the remainder after wallet credit) while the FULL proration travels
209	 * in metadata as `chargeCents`, so the confirm route debits the whole proration
210	 * back out of the wallet against the just-credited card amount. The wallet is
211	 * never touched before the card clears.
212	 */
213	export async function createDiskExpandCheckout(
214	  user: { id: string; email: string },
215	  cardCents: number,
216	  expand: { serverId: string; addGB: number; hostname?: string; prorateCents: number },
217	): Promise<string | null> {
218	  if (!stripeConfigured() || cardCents <= 0) return null;
219	  const base = process.env.APP_URL ?? "http://localhost:3000";
220	  const session = await stripe().checkout.sessions.create({
221	    mode: "payment",
222	    customer_email: user.email,
223	    line_items: [
224	      {
225	        price_data: {
226	          currency: "usd",
227	          product_data: {
228	            name: `Nxeon +${expand.addGB} GB disk${expand.hostname ? ` — ${expand.hostname}` : ""}`,
229	            // The one-way nature is on the Stripe page itself, not just in our UI.
230	            description: "Permanent storage expansion — disk space can be added but never removed.",
231	          },
232	          unit_amount: cardCents,
233	        },
234	        quantity: 1,
235	      },
236	    ],
237	    metadata: {
238	      nxeonUserId: user.id,
239	      // chargeCents = the FULL proration to debit on confirm (not the card amount).
240	      nxeonDiskExpand: packMetadata("Disk expansion intent", {
241	        serverId: expand.serverId,
242	        addGB: expand.addGB,
243	        chargeCents: expand.prorateCents,
244	      }),
245	    },
246	    success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
247	    cancel_url: `${base}/dashboard/servers/${expand.serverId}?canceled=1`,
248	  });
249	  return session.url;
250	}
