268	/**
269	 * WHAT a paid Checkout session was for — the ONE decision that routes fulfilment.
270	 *
271	 * REAL DEFECT this shape exists to remove (found 2026-07-27 audit). Fulfilment used
272	 * to ask three separate `getCheckout*Intent` helpers, each of which did its OWN
273	 * `sessions.retrieve` inside a `try` that returned `null` on ANY failure. So a
274	 * transient Stripe error — a 5xx, a rate limit, a dropped socket — turned "I could
275	 * not read this session" into "this session has no purchase metadata", and
276	 * `fulfilCheckoutSession` fell through to its plain wallet-top-up branch reporting
277	 * `fulfilled: true`. Card charged, no server, no `FulfilledSession` row, no
278	 * notification, and the webhook returns 200 so Stripe never retries. Exactly the
279	 * class of invisible failure that file was written to end, one layer up.
280	 *
281	 * `unreadable` and `unpaid` are therefore first-class answers, NOT absences. The
282	 * session is retrieved exactly once (`getCheckoutPurpose`, which THROWS rather than
283	 * returning a lie) and classified by a pure function over its metadata.
284	 */
285	export type CheckoutPurpose =
286	  | {
287	      kind: "order";
288	      userId: string;
289	      intent: OrderIntent;
290	      sold: OrderPrice | null;
291	      campaign: string;
292	      /** The first-month-free hold to confirm at fulfilment; null for a full-price order. */
293	      promoReservationToken: string | null;
294	      /** The checkout-coupon hold to confirm at fulfilment; null for a full-price order. */
295	      couponReservationToken: string | null;
296	    }
297	  | { kind: "resize"; userId: string; serverId: string; planId: string; chargeCents: number }
298	  | { kind: "diskExpand"; userId: string; serverId: string; addGB: number; chargeCents: number }
299	  /** No purchase metadata: a wallet top-up the customer bought for its own sake. */
300	  | { kind: "topup"; userId: string | null }
301	  /** Not paid (or paid to nobody) — nothing to fulfil and nothing to claim. */
302	  | { kind: "unpaid" }
303	  /** Purchase metadata IS present but cannot be trusted. Never treat as a top-up. */
304	  | { kind: "unreadable"; userId: string | null; detail: string };
305	
306	/**
307	 * Classify a retrieved session. Pure — no clock, no network, no database — so the
308	 * routing decision is unit-testable and identical for the redirect and the webhook.
309	 */
310	export function classifyCheckoutSession(
311	  session: Pick<Stripe.Checkout.Session, "metadata" | "payment_status">,
312	): CheckoutPurpose {
313	  const md = session.metadata ?? null;
314	  const userId = parseId(md?.nxeonUserId);
315	  if (!userId || session.payment_status !== "paid") return { kind: "unpaid" };
316	
317	  const orderRaw = md?.nxeonOrder;
318	  if (orderRaw) {
319	    let intent: unknown;
320	    try {
321	      intent = JSON.parse(orderRaw);
322	    } catch {
323	      return { kind: "unreadable", userId, detail: "nxeonOrder is not valid JSON" };
324	    }
325	    if (!intent || typeof intent !== "object") {
326	      return { kind: "unreadable", userId, detail: "nxeonOrder is not an object" };
327	    }
328	    return {
329	      kind: "order",
330	      userId,
331	      intent: intent as OrderIntent,
332	      sold: parseOrderPrice(session.metadata?.nxeonOrderPrice),
333	      campaign: sanitizeCampaign(md?.nxeonPromoCampaign),
334	      promoReservationToken: parseId(md?.nxeonPromoReservation),
335	      couponReservationToken: parseId(md?.nxeonCouponReservation),
336	    };
337	  }
338	
339	  const resizeRaw = md?.nxeonResize;
340	  if (resizeRaw) {
341	    let p: Record<string, unknown>;
342	    try {
343	      p = JSON.parse(resizeRaw) as Record<string, unknown>;
344	    } catch {
345	      return { kind: "unreadable", userId, detail: "nxeonResize is not valid JSON" };
346	    }
347	    const serverId = parseId(p?.serverId);
348	    const planId = parseId(p?.planId);
349	    const chargeCents = parseChargeCents(p?.chargeCents);
350	    if (!serverId || !planId || chargeCents === null) {
351	      return { kind: "unreadable", userId, detail: "nxeonResize is missing serverId/planId/chargeCents" };
352	    }
353	    return { kind: "resize", userId, serverId, planId, chargeCents };
354	  }
355	
356	  const expandRaw = md?.nxeonDiskExpand;
357	  if (expandRaw) {
358	    let p: Record<string, unknown>;
359	    try {
360	      p = JSON.parse(expandRaw) as Record<string, unknown>;
361	    } catch {
362	      return { kind: "unreadable", userId, detail: "nxeonDiskExpand is not valid JSON" };
363	    }
364	    const serverId = parseId(p?.serverId);
365	    const addGB = parseChargeCents(p?.addGB);
366	    const chargeCents = parseChargeCents(p?.chargeCents);
367	    if (!serverId || addGB === null || chargeCents === null) {
368	      return { kind: "unreadable", userId, detail: "nxeonDiskExpand is missing serverId/addGB/chargeCents" };
369	    }
370	    return { kind: "diskExpand", userId, serverId, addGB, chargeCents };
371	  }
372	
373	  return { kind: "topup", userId };
374	}
