390	/**
391	 * True when this session's card payment is the FUNDING LEG of a purchase — a VPS
392	 * order, an upgrade, a disk expansion — rather than a wallet top-up the customer
393	 * bought for its own sake.
394	 *
395	 * The wallet is the settlement bus for every card-paid purchase: the card amount
396	 * is credited in, then the purchase debits the full total back out. That credit is
397	 * plumbing, not a product, and it must not be documented as one.
398	 *
399	 * REAL INCIDENT (2026-07-26 rehearsal, H3): every paid session got a PAID "Wallet
400	 * top-up" invoice here AND a PAID invoice from whatever it funded, so one $82.53
401	 * annual purchase produced `Wallet top-up $82.53` + `Starter VPS — Annual $82.53`
402	 * and the invoices page reported $165.06 paid lifetime — a customer reconciling
403	 * against their card statement saw twice their spend. Each document was internally
404	 * consistent; there were simply two of them for one payment. worker/billing.ts
405	 * already states the rule for the renewal path: "No invoice for the card leg …
406	 * a second document for the card portion would double-count the same revenue."
407	 *
408	 * Reads the same three metadata keys `lib/fulfil-checkout.ts` dispatches on, so
409	 * "did this session fund a purchase" has one answer, not two.
410	 */
411	export function isPurchaseLegSession(metadata: Stripe.Metadata | null | undefined): boolean {
412	  return !!(metadata?.nxeonOrder || metadata?.nxeonResize || metadata?.nxeonDiskExpand);
413	}
