415	/**
416	 * Credit a user's wallet for a completed Checkout session, idempotently.
417	 * Called from both the success-redirect confirm route (works without HTTPS)
418	 * and the webhook (belt-and-suspenders once HTTPS is available).
419	 * Returns true if a credit was applied this call.
420	 *
421	 * Takes the ALREADY-RETRIEVED session rather than an id: `fulfilCheckoutSession`
422	 * fetches it once and both the credit and the fulfilment routing read that single
423	 * object, so the two can never disagree about what this payment was (and a Stripe
424	 * read failure surfaces in one place, loudly, instead of four times as `null`).
425	 */
426	export async function creditCheckoutSession(session: Stripe.Checkout.Session): Promise<boolean> {
427	  const userId = session.metadata?.nxeonUserId;
428	  const cents = session.amount_total ?? 0;
429	  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;
430	
431	  // Legacy guard: rows credited before `stripeSessionId` existed only recorded the
432	  // session id inside the description.
433	  const legacy = await db.walletTransaction.findFirst({
434	    where: { stripeSessionId: null, description: { contains: session.id } },
435	  });
436	  if (legacy) return false;
437	
438	  // Is this credit a product the customer bought, or the funding leg of something
439	  // else they bought? Only the first is a "Wallet top-up" and only the first gets
440	  // a billing document — see isPurchaseLegSession for the incident.
441	  const purchaseLeg = isPurchaseLegSession(session.metadata);
442	
443	  // Idempotency is enforced by the UNIQUE index on `stripeSessionId` — NOT by a
444	  // read-then-write check. The confirm-redirect and the webhook can arrive
445	  // concurrently (and /api/stripe/confirm is unauthenticated and replayable), so
446	  // only the database can safely decide the winner. P2002 == already credited.
447	  const ops: Prisma.PrismaPromise<unknown>[] = [
448	    db.walletTransaction.create({
449	      data: {
450	        userId,
451	        amountCents: cents,
452	        description: `Stripe payment (${session.id})`,
453	        stripeSessionId: session.id,
