190	  // Feature flag: game servers can be switched off platform-wide.
191	  if (!(await getSettingBool("feature_game_servers", true))) {
192	    return { error: "Game servers aren't available right now." };
193	  }
194	
195	  // Game servers are Server rows too, so they count toward the per-user cap
196	  // (`max_servers_per_user`, default 10; 0 = unlimited).
197	  const cap = await getSettingInt("max_servers_per_user", 10);
198	  if (cap > 0) {
199	    const owned = await db.server.count({ where: { userId: user.id, status: { notIn: ["DELETING"] } } });
200	    if (owned >= cap) {
201	      return { error: `You've reached your limit of ${cap} server${cap === 1 ? "" : "s"}.` };
202	    }
203	  }
204	
205	  const gp = await db.gamePlan.findUnique({
206	    where: { id: gamePlanId },
207	    include: { basePlan: true },
208	  });
209	  if (!gp || !gp.active) return { error: "That game plan isn't available." };
210	  if (!gp.basePlan?.active) return { error: "Provisioning is temporarily unavailable for this game." };
211	  if (!GAME_FAMILIES.includes(gp.gameFamily as GameFamily)) {
212	    return { error: "Unknown game family." };
213	  }
214	
215	  // Resolve the game image: the tier's own OsTemplate, else any active image for
216	  // this game family. A game server can't provision without an image.
217	  let osTemplateId = gp.osTemplateId;
218	  if (osTemplateId) {
219	    const os = await db.osTemplate.findUnique({ where: { id: osTemplateId } });
220	    if (!os?.active) osTemplateId = null;
221	  }
222	  if (!osTemplateId) {
223	    const os = await db.osTemplate.findFirst({
224	      where: { family: gp.gameFamily, category: "APPLICATION", active: true },
225	      orderBy: { sortOrder: "asc" },
226	    });
