246	  // annual rate resolved once, frozen onto the Server and read back at renewal —
247	  // displayed === charged === renewed. For a monthly order this equals the old flat
248	  // `gp.priceCents`, so nothing changes for the monthly term.
249	  const term = normalizeProductTerm(termMonthsRaw);
250	  const annualPct = await annualDiscountPct();
