252	  const fullCharge = termPriceCents(gameMonthly, term, annualPct);
253	  const promoCharge = Math.max(0, fullCharge - firstMonthCreditCents(fullCharge, term));
254	  const eligible = promoEnabled && (await firstMonthFreeEligible(user.id, ipHash));
255	  const anticipated = eligible ? promoCharge : fullCharge;
256	  if (user.balanceCents < anticipated) {
257	    return { error: "Insufficient balance. Top up your wallet first." };
258	  }
259	
260	  // Oversell guard — the VPS order path enforces this but game orders skipped it,
261	  // letting game servers commit host RAM past capacity. Check the base plan's
262	  // footprint before charging or enqueuing a PROVISION that can't be scheduled.
263	  const capacity = await capacityCheck(gp.basePlanId);
264	  if (!capacity.ok) return { error: capacity.reason ?? "The host is at capacity right now. Please try again shortly." };
265	
266	  const hostname = `${gp.gameFamily}-${rand()}`;
267	
268	  let server;
269	  try {
270	    server = await db.$transaction(async (tx) => {
271	      // Atomic claim inside the charge tx (mirrors lib/order.ts claimOrderCoupon).
272	      let debitCents = fullCharge;
273	      let promoClaimId: string | null = null;
274	      if (promoEnabled) {
275	        const claim = await claimFirstMonthFree(tx, {
276	          userId: user.id,
277	          ipHash,
278	          serviceType: "GAME",
279	          campaign,
280	          chargedCents: promoCharge,
281	        });
282	        if (claim.claimed) {
283	          debitCents = promoCharge;
284	          promoClaimId = claim.id;
285	        }
286	      }
287	      const note = debitCents < fullCharge ? " — First month free" : "";
288	      const effMonthly = term > 1 ? Math.round(fullCharge / term) : 0;
289	      const termLabel = term > 1 ? `${vpsTerm(term).label} ($${(effMonthly / 100).toFixed(2)}/mo)` : vpsTerm(term).label;
290	      await debitWallet(tx, user.id, debitCents);
291	      await tx.walletTransaction.create({
292	        data: {
293	          userId: user.id,
294	          amountCents: -debitCents,
295	          description: `Game server: ${gp.name} (${gp.gameFamily}) — ${termLabel}${note}`,
296	        },
297	      });
