// ---------- Customer deploy ----------

/**
 * Pre-charge gate shared by both game order entry points: an unverified address
 * means we cannot reach the person we're about to charge (email), the game-servers
 * feature can be switched off platform-wide (flag), and game servers are Server rows
 * too so they count toward the per-user cap. Returns a customer-facing error to
 * surface, or null to proceed.
 *
 * The MONEY-CRITICAL guards (plan validity, image, capacity, balance, atomic debit)
 * live in `placeGameOrder` (lib/game-order.ts), so the Stripe fulfilment path is
 * safe WITHOUT this gate — this only fronts the interactive order actions, exactly
 * as `serverLimitError` + the email check front `payAndDeploy` for VPS.
 */
async function gameOrderGate(user: User): Promise<string | null> {
  const unverified = await emailVerificationError(user);
  if (unverified) return unverified;
  if (!(await getSettingBool("feature_game_servers", true))) {
    return "Game servers aren't available right now.";
  }
  const cap = await getSettingInt("max_servers_per_user", 10);
  if (cap > 0) {
    const owned = await db.server.count({ where: { userId: user.id, status: { notIn: ["DELETING"] } } });
    if (owned >= cap) {
      return `You've reached your limit of ${cap} server${cap === 1 ? "" : "s"}.`;
    }
  }
  return null;
}

/** Extract a GameOrderIntent from the wizard's deploy form. */
function gameIntentFromFormData(formData: FormData): GameOrderIntent {
  let config: Record<string, unknown> | null = null;
  const rawConfig = formData.get("config");
  if (typeof rawConfig === "string" && rawConfig.trim() !== "") {
    try {
      const parsed = JSON.parse(rawConfig);
      if (parsed && typeof parsed === "object") config = parsed as Record<string, unknown>;
    } catch {
      // A malformed config blob is dropped, not trusted — `gameOrderQuote` then
      // fills defaults. It can never widen the charge (game is a flat term price).
      config = null;
    }
  }
  return {
    gamePlanId: String(formData.get("gamePlanId") ?? ""),
    termMonths: Number(formData.get("termMonths") ?? 1),
    serverName: String(formData.get("serverName") ?? "").trim() || undefined,
    hostname: String(formData.get("hostname") ?? "").trim() || undefined,
    variant: String(formData.get("variant") ?? "").trim() || undefined,
    config,
  };
}

/**
 * Wizard checkout for a game server — the game analogue of `payAndDeploy`, built on
 * the SAME audited machinery: it reuses `walletSplit` for the wallet/card split,
 * `placeGameOrder` (lib/game-order.ts) as the ONE debit path, and — when a card leg
 * is needed — `createGameOrderCheckout` + the shared Stripe fulfilment bus
 * (lib/fulfil-checkout.ts) that also settles VPS orders. No new charge path.
 *
 * MONEY: game bills FULL from month 1 — no first-month-free, no coupon, no VAT
 * change. The charge is the DB-fed term price (`gameOrderQuote.chargeCents`), the
 * SOLD price is stamped on the Checkout session BEFORE the card is charged, and
 * fulfilment settles that exact figure (never re-quoted after the card cleared).
 * displayed (wizard) === charged (here) === renewed (renewalCharge).
 */
export async function payAndDeployGame(
  _prev: unknown,
  formData: FormData,
): Promise<{ error?: string; checkoutUrl?: string }> {
  const user = await requireUser();
  // Spend path: never move a customer's money while an admin is impersonating them.
  await assertNotImpersonating();
  const gateErr = await gameOrderGate(user);
  if (gateErr) return { error: gateErr };

  const intent = gameIntentFromFormData(formData);

  let quote;
  try {
    quote = await gameOrderQuote(intent);
  } catch (e) {
    if (e instanceof GameOrderError) return { error: e.message };
    throw e;
  }

  // The full, DB-fed term price. No promo/coupon/VAT adjustment for game.
  const chargeCents = quote.chargeCents;

  // Wallet-aware split — the wizard computes the identical split (lib/wallet-split.ts)
  // from the same inputs, so what the customer sees === what we charge. `useWallet`
  // defaults ON (only "0" turns it off).
  const useWallet = formData.get("useWallet") !== "0";
  const { cardCents } = walletSplit({ dueCents: chargeCents, balanceCents: user.balanceCents, useWallet });

  // Card portion is $0 (the wallet covers the whole charge) → provision straight
  // away through the audited debit. `placeGameOrder` debits the FULL chargeCents
  // from the wallet; its balance check holds because cardCents <= 0 means the
  // balance already covers the charge.
  if (cardCents <= 0) {
    let serverId: string;
    try {
      serverId = await placeGameOrder(user, intent, null);
    } catch (e) {
      if (e instanceof GameOrderError) return { error: e.message };
      throw e;
    }
    redirect(`/dashboard/servers/${serverId}`);
  }

  // Card leg > 0 → charge ONLY the remainder on the card. On payment success the
  // confirm/webhook route credits this card amount to the wallet and THEN
  // placeGameOrder debits the full chargeCents, so the wallet naturally absorbs the
  // applied balance and the card the rest — the wallet is never touched before the
  // card clears. The SOLD price is handed over EXPLICITLY (stamped before any
  // charge), so a rate change between now and fulfilment can't re-price it.
  const sold: GameOrderPrice = { chargeCents };
  let url: string | null;
  try {
    url = await createGameOrderCheckout(user, cardCents, intent, sold);
  } catch (e) {
    if (e instanceof GameOrderError) return { error: e.message };
    throw e;
  }
  if (!url) {
    return { error: "Card payments aren't set up yet — top up your wallet to deploy." };
  }
  return { checkoutUrl: url };
}

/**
 * Legacy one-click wallet deploy, SUPERSEDED by `payAndDeployGame` + the
 * GameDeployWizard. Kept as a thin, wallet-only wrapper over the audited core so any
 * remaining caller keeps working: it charges the tier's DB-fed term price from the
 * wallet (full price — game has no first-month-free) and never opens a card leg.
 */
export async function orderGameServer(gamePlanId: string, termMonthsRaw?: number): Promise<Result> {
  const user = await requireUser();
  await assertNotImpersonating();
  const gateErr = await gameOrderGate(user);
  if (gateErr) return { error: gateErr };

  let serverId: string;
  try {
    serverId = await placeGameOrder(user, { gamePlanId, termMonths: Number(termMonthsRaw ?? 1) }, null);
  } catch (e) {
    if (e instanceof GameOrderError) return { error: e.message };
    throw e;
  }
  redirect(`/dashboard/servers/${serverId}`);
}

