"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { useActionState } from "react";
import { payAndDeployGame } from "@/lib/actions-gameplans";
import { GameLogo } from "@/components/marketing/GameLogo";
import { TermLadder } from "@/components/customer/TermLadder";
import {
  PRODUCT_TERMS,
  ANNUAL_TERM_MONTHS,
  termPriceCents,
  vpsTerm,
  DEFAULT_ANNUAL_DISCOUNT_PCT,
} from "@/lib/billing-terms";
import { walletSplit } from "@/lib/wallet-split";
import type { ConfigField, FamilySchema } from "@/lib/game-config";

export type Tier = {
  id: string;
  gameFamily: string;
  name: string;
  ramMB: number;
  cpuCores: number;
  diskGB: number;
  slots: number | null;
  priceCents: number;
  termMonths: number;
  featured: boolean;
};
export type GameMeta = { family: string; name: string; glyph: string };

const money = (c: number) => `$${(c / 100).toFixed(2)}`;
const gb = (mb: number) => `${(mb / 1024).toFixed(mb % 1024 ? 1 : 0)} GB`;

/** Same hostname rule as the server (lib/game-order.ts) + VPS deploy. */
const HOSTNAME_RE = /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i;
type Values = Record<string, string | number | boolean>;

/** sessionStorage key for the in-progress order — survives the Stripe round-trip. */
const DRAFT_KEY = "nxeon.gamedeploy.draft.v1";

/** Compact stepper, matching the VPS DeployWizard. */
function Stepper({ step, steps }: { step: number; steps: string[] }) {
  return (
    <div className="mb-6 flex flex-wrap items-center gap-2 text-xs">
      {steps.map((s, i) => (
        <div key={s} className="flex items-center gap-2">
          <span
            className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] font-semibold ${
              i === step
                ? "border-brand-400 bg-brand-500/20 text-brand-200"
                : i < step
                  ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300"
                  : "border-white/10 text-slate-500"
            }`}
          >
            {i < step ? "✓" : i + 1}
          </span>
          <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
          {i < steps.length - 1 && <span className="mx-1 text-slate-700">→</span>}
        </div>
      ))}
    </div>
  );
}

/** Build the default gameplay values for a family schema. */
function defaultValues(schema: FamilySchema | null): Values {
  const out: Values = {};
  if (!schema) return out;
  for (const f of schema.fields) out[f.key] = f.default;
  return out;
}

/**
 * A proper multi-step game-server deploy wizard — the game analogue of the VPS
 * DeployWizard. Steps: Game → Plan & term → Server settings → Review & checkout.
 *
 * TRUTH BY CONSTRUCTION: every price is derived from the tier's real DB price
 * (`priceCents`) run through `termPriceCents` with the SAME live `annualDiscountPct`
 * the server charges and renews at, and the wallet/card split is the same
 * `walletSplit` math the action charges. So what the customer sees === what
 * `payAndDeployGame` charges. Game bills FULL from month 1 — no first-month-free.
 */
export function GameDeployWizard({
  games,
  tiers,
  balanceCents,
  annualDiscountPct = DEFAULT_ANNUAL_DISCOUNT_PCT,
  schemas,
  stripeConfigured,
}: {
  games: GameMeta[];
  tiers: Tier[];
  balanceCents: number;
  annualDiscountPct?: number;
  /** family → per-game customization schema (only families that have one). */
  schemas: Record<string, FamilySchema>;
  /** Whether card checkout is available (else wallet-only). */
  stripeConfigured: boolean;
}) {
  const [state, action, pending] = useActionState(payAndDeployGame, {} as { error?: string; checkoutUrl?: string });

  // Only redirect to Stripe as the result of an EXPLICIT Deploy submit (armed in the
  // Deploy button's onClick), so a stale checkoutUrl can never redirect on its own.
  const submittedRef = useRef(false);
  useEffect(() => {
    if (state?.checkoutUrl && submittedRef.current) {
      submittedRef.current = false;
      window.location.href = state.checkoutUrl;
    }
  }, [state]);

  const steps = ["Game", "Plan", "Settings", "Review"];
  const [step, setStep] = useState(0);

  const firstGame = games[0]?.family ?? "";
  const [game, setGame] = useState(firstGame);
  const [selected, setSelected] = useState<string | null>(null);
  const [termMonths, setTermMonths] = useState(ANNUAL_TERM_MONTHS);
  const [serverName, setServerName] = useState("");
  const [hostname, setHostname] = useState("");
  const [variant, setVariant] = useState("");
  const [values, setValues] = useState<Values>({});
  const [useWallet, setUseWallet] = useState(balanceCents > 0);
  const [restoredAfterCancel, setRestoredAfterCancel] = useState(false);

  const gameTiers = useMemo(
    () => tiers.filter((t) => t.gameFamily === game).sort((a, b) => a.priceCents - b.priceCents),
    [tiers, game],
  );
  const chosen = gameTiers.find((t) => t.id === selected) ?? null;
  const schema = schemas[game] ?? null;

  // When the game changes, reset the tier + per-game setup to that game's defaults.
  function pickGame(family: string) {
    setGame(family);
    setSelected(null);
    const s = schemas[family] ?? null;
    setVariant(s?.defaultVariant ?? "");
    setValues(defaultValues(s));
  }

  // Restore a cancelled-checkout draft (Stripe cancel → /dashboard/games?canceled=1).
  useEffect(() => {
    let canceled = false;
    try {
      canceled = new URLSearchParams(window.location.search).get("canceled") === "1";
    } catch {
      /* no URL access */
    }
    if (!canceled) return;
    setRestoredAfterCancel(true);
    let d: any = null;
    try {
      const raw = sessionStorage.getItem(DRAFT_KEY);
      sessionStorage.removeItem(DRAFT_KEY);
      if (raw) d = JSON.parse(raw);
    } catch {
      d = null;
    }
    if (!d) return;
    // Re-check every id against the props actually rendered — a tier can be retired
    // while the customer is on Stripe's page.
    if (typeof d.game === "string" && games.some((g) => g.family === d.game)) setGame(d.game);
    if (typeof d.selected === "string" && tiers.some((t) => t.id === d.selected)) setSelected(d.selected);
    if (PRODUCT_TERMS.some((t) => t.months === d.termMonths)) setTermMonths(d.termMonths);
    if (typeof d.serverName === "string") setServerName(d.serverName);
    if (typeof d.hostname === "string") setHostname(d.hostname);
    if (typeof d.variant === "string") setVariant(d.variant);
    if (d.values && typeof d.values === "object") setValues(d.values);
    if (typeof d.useWallet === "boolean") setUseWallet(d.useWallet && balanceCents > 0);
    if (Number.isInteger(d.step) && d.step >= 0 && d.step < steps.length) setStep(d.step);
    // Mount-only: restores a one-shot draft.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Persist the draft on every change so it survives the Stripe round-trip.
  useEffect(() => {
    try {
      sessionStorage.setItem(
        DRAFT_KEY,
        JSON.stringify({ step, game, selected, termMonths, serverName, hostname, variant, values, useWallet }),
      );
    } catch {
      /* storage disabled — the wizard still works */
    }
  }, [step, game, selected, termMonths, serverName, hostname, variant, values, useWallet]);

  // Pricing — identical math to lib/game-order.ts gameOrderQuote, so displayed === charged.
  const monthlyCents = chosen ? Math.round(chosen.priceCents / Math.max(1, chosen.termMonths)) : 0;
  const chargeCents = chosen ? termPriceCents(monthlyCents, termMonths, annualDiscountPct) : 0;
  const dueCents = chargeCents;
  const split = walletSplit({ dueCents, balanceCents, useWallet });
  const walletApplied = split.walletApplied;
  const cardCents = split.cardCents;

  const hostnameValid = hostname === "" || (hostname.length >= 3 && hostname.length <= 40 && HOSTNAME_RE.test(hostname));
  // A card leg with no Stripe configured can't settle — the customer must apply
  // enough wallet balance to cover the whole charge.
  const cardBlocked = cardCents > 0 && !stripeConfigured;

  const curLabel = steps[step];
  const isLast = step === steps.length - 1;

  // Per-step gating with a plain-language blocker (mirrors DeployWizard).
  const planBlocker = !chosen ? "Choose a plan to continue." : null;
  const settingsBlocker = !hostnameValid
    ? "Hostname must be 3–40 characters, using only letters, digits and hyphens (or leave it blank and we'll name it)."
    : null;
  const deployBlocker = !chosen
    ? "Go back to the Plan step and choose a plan."
    : !hostnameValid
      ? "Fix the hostname on the Settings step."
      : cardBlocked
        ? "Card checkout isn't set up — apply enough wallet balance to cover the total, or top up your wallet."
        : null;
  const primaryBlocker = isLast
    ? deployBlocker
    : curLabel === "Plan"
      ? planBlocker
      : curLabel === "Settings"
        ? settingsBlocker
        : null;

  const canDeploy = !!chosen && hostnameValid && !cardBlocked;

  function setField(key: string, v: string | number | boolean) {
    setValues((cur) => ({ ...cur, [key]: v }));
  }

  return (
    <form
      action={action}
      // Block implicit submit everywhere but the final Review step (a stray Enter in
      // the hostname field would otherwise deploy immediately). Deploy only ever
      // happens via the explicit button.
      onKeyDown={(e) => {
        if (e.key === "Enter" && (e.target as HTMLElement).tagName !== "TEXTAREA" && !isLast) {
          e.preventDefault();
        }
      }}
      onSubmit={(e) => {
        if (!isLast) {
          e.preventDefault();
          e.stopPropagation();
        }
      }}
    >
      {/* Hidden fields — the ONE source the action reads, kept in sync with the UI. */}
      <input type="hidden" name="gamePlanId" value={chosen?.id ?? ""} />
      <input type="hidden" name="termMonths" value={termMonths} />
      <input type="hidden" name="serverName" value={serverName} />
      <input type="hidden" name="hostname" value={hostname} />
      <input type="hidden" name="variant" value={variant} />
      <input type="hidden" name="config" value={JSON.stringify(values)} />
      <input type="hidden" name="useWallet" value={useWallet ? "1" : "0"} />

      <div className="card">
        <Stepper step={step} steps={steps} />
        {state?.error && (
          <div className="mb-4 rounded-xl border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">
            {state.error}
          </div>
        )}
        {restoredAfterCancel && (
          <div className="mb-4 rounded-xl border border-white/[0.08] bg-white/[0.03] px-3 py-2 text-sm text-slate-300">
            <span className="font-semibold text-white">Checkout cancelled — you weren&apos;t charged.</span>{" "}
            Your game, plan, term and settings are exactly as you left them.
          </div>
        )}

        {/* Step 1 — Game */}
        {curLabel === "Game" && (
          <div>
            <h2 className="mb-1 font-semibold">Choose your game</h2>
            <p className="mb-4 text-sm text-slate-400">Pick a game and we&apos;ll size the server for it.</p>
            <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-6">
              {games.map((g) => {
                const active = g.family === game;
                const count = tiers.filter((t) => t.gameFamily === g.family).length;
                return (
                  <button
                    type="button"
                    key={g.family}
                    onClick={() => pickGame(g.family)}
                    className={`card card-hover flex flex-col items-center gap-1.5 py-4 text-center transition ${
                      active ? "!border-brand-400 ring-1 ring-brand-400/40" : ""
                    }`}
                  >
                    <GameLogo family={g.family} size={40} />
                    <span className="text-sm font-medium text-white">{g.name}</span>
                    <span className="text-[11px] text-slate-500">
                      {count} tier{count === 1 ? "" : "s"}
                    </span>
                  </button>
                );
              })}
            </div>
          </div>
        )}

        {/* Step 2 — Plan & term */}
        {curLabel === "Plan" && (
          <div className="space-y-6">
            <div>
              <div className="mb-3 flex items-center gap-2">
                <GameLogo family={game} size={26} />
                <h2 className="font-semibold">Choose your {games.find((g) => g.family === game)?.name ?? "game"} plan</h2>
              </div>
              {gameTiers.length === 0 ? (
                <p className="text-sm text-slate-500">No plans are available for this game yet. Check back soon.</p>
              ) : (
                <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
                  {gameTiers.map((t) => {
                    const active = t.id === selected;
                    const tMonthly = Math.round(t.priceCents / Math.max(1, t.termMonths));
                    const tPerMo = Math.round(termPriceCents(tMonthly, termMonths, annualDiscountPct) / termMonths);
                    return (
                      <button
                        type="button"
                        key={t.id}
                        onClick={() => setSelected(t.id)}
                        className={`card card-hover text-left transition ${
                          active ? "!border-brand-400 ring-1 ring-brand-400/40" : ""
                        }`}
                      >
                        <div className="flex items-center justify-between gap-2">
                          <span className="font-semibold text-white">{t.name}</span>
                          {t.featured && (
                            <span className="rounded-full border border-brand-500/40 bg-brand-500/10 px-2 py-0.5 text-[11px] text-brand-300">
                              Popular
                            </span>
                          )}
                        </div>
                        <p className="mt-2 text-2xl font-bold tracking-tight text-white">
                          {money(tPerMo)}
                          <span className="text-sm font-normal text-slate-400">/mo</span>
                        </p>
                        <ul className="mt-3 space-y-1 text-sm text-slate-400">
                          <li>
                            {gb(t.ramMB)} RAM · {t.cpuCores} vCPU
                          </li>
                          <li>{t.diskGB} GB NVMe disk</li>
                          {t.slots != null && <li>Up to {t.slots} player slots</li>}
                        </ul>
                      </button>
                    );
                  })}
                </div>
              )}
            </div>

            {chosen && (
              <div>
                <p className="label mb-2">Billing term</p>
                <TermLadder
                  monthlyCents={monthlyCents}
                  annualDiscountPct={annualDiscountPct}
                  value={termMonths}
                  onChange={setTermMonths}
                />
                <p className="mt-2 text-xs text-slate-500">
                  Billed in full from day one — the price you sign up at is the price you renew at.
                </p>
              </div>
            )}
          </div>
        )}

        {/* Step 3 — Server settings */}
        {curLabel === "Settings" && (
          <div className="space-y-5">
            <div>
              <h2 className="font-semibold">Server settings</h2>
              <p className="mt-1 text-sm text-slate-400">
                Name your server and set it up for {games.find((g) => g.family === game)?.name ?? "your game"}. You can
                change everything later from the server&apos;s Game settings tab.
              </p>
            </div>

            <div className="grid gap-4 sm:grid-cols-2">
              <label className="block text-sm">
                <span className="label mb-1.5 block">
                  Server name <span className="text-xs font-normal text-slate-500">optional</span>
                </span>
                <input
                  className="input"
                  value={serverName}
                  maxLength={60}
                  onChange={(e) => setServerName(e.target.value)}
                  placeholder="My Survival Server"
                />
                <span className="mt-1 block text-xs text-slate-500">A friendly nickname shown in your dashboard.</span>
              </label>
              <label className="block text-sm">
                <span className="label mb-1.5 block">
                  Hostname <span className="text-xs font-normal text-slate-500">optional</span>
                </span>
                <input
                  className="input"
                  value={hostname}
                  onChange={(e) => setHostname(e.target.value.toLowerCase())}
                  placeholder="auto-generated"
                  aria-invalid={!hostnameValid}
                />
                <span className={`mt-1 block text-xs ${!hostnameValid ? "text-red-300" : "text-slate-500"}`}>
                  {!hostnameValid
                    ? "3–40 characters, letters, digits and hyphens only."
                    : "The name your server answers to — leave blank and we'll pick one."}
                </span>
              </label>
            </div>

            {schema ? (
              <>
                <div>
                  <span className="label mb-1.5 block">Server type</span>
                  <select className="input max-w-sm" value={variant} onChange={(e) => setVariant(e.target.value)}>
                    {schema.variants.map((v) => (
                      <option key={v.id} value={v.id}>
                        {v.label}
                      </option>
                    ))}
                  </select>
                  {schema.variants.find((v) => v.id === variant)?.description && (
                    <p className="mt-1.5 text-xs text-slate-500">
                      {schema.variants.find((v) => v.id === variant)?.description}
                    </p>
                  )}
                </div>
                <SettingsFields schema={schema} values={values} onChange={setField} />
              </>
            ) : (
              <p className="rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2 text-xs text-slate-400">
                This game has no extra options to configure up front — it deploys ready to play.
              </p>
            )}
          </div>
        )}

        {/* Step 4 — Review & checkout */}
        {curLabel === "Review" && (
          <div>
            <h2 className="mb-4 font-semibold">Review &amp; deploy</h2>
            <dl className="space-y-2 text-sm">
              <Row k="Game" v={games.find((g) => g.family === game)?.name ?? game} />
              <Row k="Plan" v={chosen ? `${chosen.name} · ${gb(chosen.ramMB)} / ${chosen.cpuCores} vCPU / ${chosen.diskGB} GB` : "—"} />
              {chosen?.slots != null && <Row k="Slots" v={`Up to ${chosen.slots} players`} />}
              <Row k="Billing term" v={vpsTerm(termMonths).label} />
              <Row k="Server name" v={serverName || "—"} />
              <Row k="Hostname" v={hostname || "auto-generated"} />
              {schema && <Row k="Server type" v={schema.variants.find((v) => v.id === variant)?.label ?? variant} />}

              <div className="divider" />
              <Row
                k="Due today"
                v={<span className="text-base font-semibold">{money(dueCents)}</span>}
              />
              {balanceCents > 0 && (
                <label className="flex items-center justify-between gap-3 rounded-lg border border-white/[0.06] bg-white/[0.02] px-3 py-2">
                  <span className="flex items-center gap-2 text-slate-300">
                    <input type="checkbox" checked={useWallet} onChange={(e) => setUseWallet(e.target.checked)} />
                    Apply my balance ({money(balanceCents)})
                  </span>
                  <span className="text-xs text-slate-500">{useWallet ? "applied" : "off"}</span>
                </label>
              )}
              {walletApplied > 0 && (
                <Row k="Wallet credit" v={<span className="text-emerald-300">−{money(walletApplied)}</span>} />
              )}
              <Row
                k={cardCents > 0 ? "Pay by card" : "Paid from wallet"}
                v={<span className="text-base font-semibold">{cardCents > 0 ? money(cardCents) : "$0 card"}</span>}
              />
              <Row
                k="Wallet after"
                v={
                  <span className={balanceCents - walletApplied < 0 ? "text-red-300" : "text-emerald-300"}>
                    {money(balanceCents - walletApplied)}
                  </span>
                }
              />
            </dl>
            {split.clampedForStripeMin && (
              <p className="mt-3 text-xs text-amber-300">
                Card payments have a {money(50)} minimum, so we&apos;ll charge {money(cardCents)} to your card and apply
                the rest ({money(walletApplied)}) from your wallet.
              </p>
            )}
            {cardCents > 0 && stripeConfigured && (
              <p className="mt-3 text-sm text-slate-400">
                You&apos;ll pay <span className="text-slate-200">{money(cardCents)}</span> securely by card at checkout
                {walletApplied > 0 ? <> — with {money(walletApplied)} covered from your wallet</> : null}, and your
                server deploys the moment payment clears. Your card is kept on file so renewals run automatically.
              </p>
            )}
          </div>
        )}

        {primaryBlocker && (
          <p
            id="game-wizard-blocker"
            className="mt-6 rounded-lg border border-amber-500/25 bg-amber-500/10 px-3 py-2 text-xs text-amber-300"
          >
            {primaryBlocker}
          </p>
        )}

        <div className="mt-6 flex items-center justify-between">
          <button
            type="button"
            className="btn-ghost"
            disabled={step === 0}
            onClick={() => setStep((s) => Math.max(0, s - 1))}
          >
            ← Back
          </button>
          {!isLast ? (
            <button
              key="game-wizard-continue"
              type="button"
              className="btn-primary"
              disabled={!!primaryBlocker}
              aria-describedby={primaryBlocker ? "game-wizard-blocker" : undefined}
              onClick={() => setStep((s) => s + 1)}
            >
              Continue →
            </button>
          ) : (
            <button
              key="game-wizard-deploy"
              type="submit"
              className="btn-primary px-6"
              disabled={pending || !canDeploy}
              aria-describedby={deployBlocker ? "game-wizard-blocker" : undefined}
              onClick={() => {
                submittedRef.current = true;
              }}
            >
              {pending
                ? "Deploying…"
                : cardCents > 0
                  ? `Deploy — ${money(cardCents)} on card`
                  : "Deploy — paid from wallet"}
            </button>
          )}
        </div>
      </div>
    </form>
  );
}

/** Per-game gameplay fields, grouped by their `group` heading. */
function SettingsFields({
  schema,
  values,
  onChange,
}: {
  schema: FamilySchema;
  values: Values;
  onChange: (key: string, v: string | number | boolean) => void;
}) {
  const groups = useMemo(() => {
    const map = new Map<string, ConfigField[]>();
    for (const f of schema.fields) {
      if (!map.has(f.group)) map.set(f.group, []);
      map.get(f.group)!.push(f);
    }
    return [...map.entries()];
  }, [schema]);

  return (
    <div className="space-y-5">
      {groups.map(([group, fields]) => (
        <div key={group}>
          <p className="section-label">{group}</p>
          <div className="mt-3 grid gap-4 sm:grid-cols-2">
            {fields.map((f) => (
              <GameField key={f.key} field={f} value={values[f.key]} onChange={(v) => onChange(f.key, v)} />
            ))}
          </div>
        </div>
      ))}
    </div>
  );
}

function GameField({
  field,
  value,
  onChange,
}: {
  field: ConfigField;
  value: string | number | boolean | undefined;
  onChange: (v: string | number | boolean) => void;
}) {
  if (field.type === "bool") {
    const on = value === true;
    return (
      <div className="flex items-center justify-between gap-4 rounded-xl border border-white/[0.06] bg-navy-950/40 px-3.5 py-3">
        <span className="text-sm">
          <span className="font-medium">{field.label}</span>
          {field.help && <span className="mt-0.5 block text-xs text-slate-500">{field.help}</span>}
        </span>
        <button
          type="button"
          role="switch"
          aria-checked={on}
          onClick={() => onChange(!on)}
          className={`relative inline-flex h-6 w-11 shrink-0 items-center rounded-full transition-colors ${
            on ? "bg-brand-500" : "bg-white/15"
          }`}
        >
          <span
            className={`inline-block h-5 w-5 transform rounded-full bg-white shadow transition-transform ${
              on ? "translate-x-5" : "translate-x-0.5"
            }`}
          />
        </button>
      </div>
    );
  }

  return (
    <label className="block text-sm">
      <span className="mb-1.5 flex items-baseline justify-between gap-2">
        <span className="font-medium">{field.label}</span>
        {field.phase === "deploy" && (
          <span className="text-[10px] uppercase tracking-wide text-slate-500">applied at deploy</span>
        )}
      </span>
      {field.type === "enum" ? (
        <select className="input" value={String(value ?? field.default)} onChange={(e) => onChange(e.target.value)}>
          {field.options?.map((o) => (
            <option key={o.value} value={o.value}>
              {o.label}
            </option>
          ))}
        </select>
      ) : field.type === "int" ? (
        <input
          className="input"
          type="number"
          value={value === undefined || value === null ? Number(field.default) : Number(value)}
          min={field.min}
          max={field.max}
          step={1}
          onChange={(e) => onChange(e.target.value === "" ? ("" as unknown as number) : Number(e.target.value))}
        />
      ) : (
        <input
          className="input"
          type="text"
          value={String(value ?? field.default)}
          maxLength={256}
          onChange={(e) => onChange(e.target.value)}
        />
      )}
      {field.help && <span className="mt-1 block text-xs text-slate-500">{field.help}</span>}
    </label>
  );
}

function Row({ k, v }: { k: string; v: React.ReactNode }) {
  return (
    <div className="flex items-center justify-between">
      <dt className="text-slate-400">{k}</dt>
      <dd className="text-right">{v}</dd>
    </div>
  );
}

