165	// ---------- Customer deploy ----------
166	
167	/**
168	 * Pre-charge gate shared by both game order entry points: an unverified address
169	 * means we cannot reach the person we're about to charge (email), the game-servers
170	 * feature can be switched off platform-wide (flag), and game servers are Server rows
171	 * too so they count toward the per-user cap. Returns a customer-facing error to
172	 * surface, or null to proceed.
173	 *
174	 * The MONEY-CRITICAL guards (plan validity, image, capacity, balance, atomic debit)
175	 * live in `placeGameOrder` (lib/game-order.ts), so the Stripe fulfilment path is
176	 * safe WITHOUT this gate — this only fronts the interactive order actions, exactly
177	 * as `serverLimitError` + the email check front `payAndDeploy` for VPS.
178	 */
179	async function gameOrderGate(user: User): Promise<string | null> {
180	  const unverified = await emailVerificationError(user);
181	  if (unverified) return unverified;
182	  if (!(await getSettingBool("feature_game_servers", true))) {
183	    return "Game servers aren't available right now.";
184	  }
185	  const cap = await getSettingInt("max_servers_per_user", 10);
186	  if (cap > 0) {
187	    const owned = await db.server.count({ where: { userId: user.id, status: { notIn: ["DELETING"] } } });
188	    if (owned >= cap) {
189	      return `You've reached your limit of ${cap} server${cap === 1 ? "" : "s"}.`;
190	    }
191	  }
192	  return null;
193	}
194	
195	/** Extract a GameOrderIntent from the wizard's deploy form. */
196	function gameIntentFromFormData(formData: FormData): GameOrderIntent {
197	  let config: Record<string, unknown> | null = null;
198	  const rawConfig = formData.get("config");
199	  if (typeof rawConfig === "string" && rawConfig.trim() !== "") {
200	    try {
201	      const parsed = JSON.parse(rawConfig);
202	      if (parsed && typeof parsed === "object") config = parsed as Record<string, unknown>;
203	    } catch {
204	      // A malformed config blob is dropped, not trusted — `gameOrderQuote` then
205	      // fills defaults. It can never widen the charge (game is a flat term price).
206	      config = null;
207	    }
208	  }
209	  return {
210	    gamePlanId: String(formData.get("gamePlanId") ?? ""),
211	    termMonths: Number(formData.get("termMonths") ?? 1),
212	    serverName: String(formData.get("serverName") ?? "").trim() || undefined,
213	    hostname: String(formData.get("hostname") ?? "").trim() || undefined,
214	    variant: String(formData.get("variant") ?? "").trim() || undefined,
215	    config,
216	  };
217	}
218	
219	/**
220	 * Wizard checkout for a game server — the game analogue of `payAndDeploy`, built on
221	 * the SAME audited machinery: it reuses `walletSplit` for the wallet/card split,
222	 * `placeGameOrder` (lib/game-order.ts) as the ONE debit path, and — when a card leg
223	 * is needed — `createGameOrderCheckout` + the shared Stripe fulfilment bus
224	 * (lib/fulfil-checkout.ts) that also settles VPS orders. No new charge path.
225	 *
226	 * MONEY: game bills FULL from month 1 — no first-month-free, no coupon, no VAT
227	 * change. The charge is the DB-fed term price (`gameOrderQuote.chargeCents`), the
228	 * SOLD price is stamped on the Checkout session BEFORE the card is charged, and
229	 * fulfilment settles that exact figure (never re-quoted after the card cleared).
230	 * displayed (wizard) === charged (here) === renewed (renewalCharge).
231	 */
232	export async function payAndDeployGame(
233	  _prev: unknown,
234	  formData: FormData,
235	): Promise<{ error?: string; checkoutUrl?: string }> {
236	  const user = await requireUser();
237	  // Spend path: never move a customer's money while an admin is impersonating them.
238	  await assertNotImpersonating();
239	  const gateErr = await gameOrderGate(user);
240	  if (gateErr) return { error: gateErr };
241	
242	  const intent = gameIntentFromFormData(formData);
243	
244	  let quote;
245	  try {
246	    quote = await gameOrderQuote(intent);
247	  } catch (e) {
248	    if (e instanceof GameOrderError) return { error: e.message };
249	    throw e;
250	  }
251	
252	  // The full, DB-fed term price. No promo/coupon/VAT adjustment for game.
253	  const chargeCents = quote.chargeCents;
254	
255	  // Wallet-aware split — the wizard computes the identical split (lib/wallet-split.ts)
256	  // from the same inputs, so what the customer sees === what we charge. `useWallet`
257	  // defaults ON (only "0" turns it off).
258	  const useWallet = formData.get("useWallet") !== "0";
259	  const { cardCents } = walletSplit({ dueCents: chargeCents, balanceCents: user.balanceCents, useWallet });
260	
261	  // Card portion is $0 (the wallet covers the whole charge) → provision straight
262	  // away through the audited debit. `placeGameOrder` debits the FULL chargeCents
263	  // from the wallet; its balance check holds because cardCents <= 0 means the
264	  // balance already covers the charge.
265	  if (cardCents <= 0) {
266	    let serverId: string;
267	    try {
268	      serverId = await placeGameOrder(user, intent, null);
269	    } catch (e) {
270	      if (e instanceof GameOrderError) return { error: e.message };
271	      throw e;
272	    }
273	    redirect(`/dashboard/servers/${serverId}`);
274	  }
275	
276	  // Card leg > 0 → charge ONLY the remainder on the card. On payment success the
277	  // confirm/webhook route credits this card amount to the wallet and THEN
278	  // placeGameOrder debits the full chargeCents, so the wallet naturally absorbs the
279	  // applied balance and the card the rest — the wallet is never touched before the
280	  // card clears. The SOLD price is handed over EXPLICITLY (stamped before any
281	  // charge), so a rate change between now and fulfilment can't re-price it.
282	  const sold: GameOrderPrice = { chargeCents };
283	  let url: string | null;
284	  try {
285	    url = await createGameOrderCheckout(user, cardCents, intent, sold);
286	  } catch (e) {
287	    if (e instanceof GameOrderError) return { error: e.message };
288	    throw e;
289	  }
290	  if (!url) {
291	    return { error: "Card payments aren't set up yet — top up your wallet to deploy." };
292	  }
293	  return { checkoutUrl: url };
294	}
295	
296	/**
297	 * Legacy one-click wallet deploy, SUPERSEDED by `payAndDeployGame` + the
298	 * GameDeployWizard. Kept as a thin, wallet-only wrapper over the audited core so any
299	 * remaining caller keeps working: it charges the tier's DB-fed term price from the
300	 * wallet (full price — game has no first-month-free) and never opens a card leg.
301	 */
302	export async function orderGameServer(gamePlanId: string, termMonthsRaw?: number): Promise<Result> {
303	  const user = await requireUser();
304	  await assertNotImpersonating();
305	  const gateErr = await gameOrderGate(user);
306	  if (gateErr) return { error: gateErr };
307	
308	  let serverId: string;
309	  try {
310	    serverId = await placeGameOrder(user, { gamePlanId, termMonths: Number(termMonthsRaw ?? 1) }, null);
311	  } catch (e) {
312	    if (e instanceof GameOrderError) return { error: e.message };
313	    throw e;
314	  }

